// Rules Rescue — Cloudflare Worker (rules.elie.place)
// Sert la page, et lit les cartes Rules d'une adresse via l'API publique de Voyager.
const CONTRACT = "0x05b456031650c1de9eec123d3e7d06a684d321a346d4a7cac9fd86c2b77cf70f";
const UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130 Safari/537.36";
const H = { "user-agent": UA, accept: "application/json", referer: "https://voyager.online/" };
const RAR = { common: "C", holographic: "H", platinium: "P", platinum: "P", halloween: "W" };
const HTML = "<!doctype html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><title>Rules Rescue</title><meta name=\"description\" content=\"Retrouver et r\u00e9cup\u00e9rer ses cartes Rules (rules.art) sur Starknet apr\u00e8s la fermeture du site.\"><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Archivo+Black&family=Inter:wght@400;500;600;700&family=Inconsolata:wght@500;700&display=swap\"><style>\n/* Layout: classeur de collection \u2014 bandeau compteur, rail de filtres collant, grille de cartes au format 0.63 */\n:root {\n  --bg: #0d1114;\n  --surface: #191b1d;\n  --line: #33373b;\n  --fg: #f7f7f7;\n  --muted: #828585;\n  --accent: #9f04dc;\n  --accent-soft: rgba(159, 4, 220, .16);\n  --holo: #56c8fe;\n  --plat: #e7e7e7;\n  --hallo: #e0672a;\n  --chip-fg: #f7f7f7;\n  --display: \"Archivo Black\", \"Arial Black\", Impact, sans-serif;\n  --body: \"Inter\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n  --mono: \"Inconsolata\", ui-monospace, \"SFMono-Regular\", Menlo, monospace;\n  color-scheme: dark;\n}\n@media (prefers-color-scheme: light) {\n  :root:not([data-theme=\"dark\"]) {\n    --bg: #eceeef; --surface: #ffffff; --line: #cfd3d6; --fg: #0d1114; --muted: #5d6266;\n    --accent: #8d04c3; --accent-soft: rgba(141, 4, 195, .1); --holo: #0a86c2; --plat: #6d7378; --hallo: #b8471a; --chip-fg: #ffffff;\n    color-scheme: light;\n  }\n}\n:root[data-theme=\"light\"] {\n  --bg: #eceeef; --surface: #ffffff; --line: #cfd3d6; --fg: #0d1114; --muted: #5d6266;\n  --accent: #8d04c3; --accent-soft: rgba(141, 4, 195, .1); --holo: #0a86c2; --plat: #6d7378; --hallo: #b8471a; --chip-fg: #ffffff;\n  color-scheme: light;\n}\n* { box-sizing: border-box; }\nbody { background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 15px; line-height: 1.5; }\nbody::before { content: \"\"; position: fixed; inset: 0 0 auto; height: env(safe-area-inset-top, 0px); z-index: 10; background: var(--bg); }\n.wrap { max-width: 1320px; margin: 0 auto; padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); }\n\n/* Bandeau */\nheader { padding-block: 40px 24px; display: grid; gap: 20px; }\n.brand { display: flex; align-items: center; gap: 12px; font-family: var(--mono); font-size: 13px; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }\n.brand svg { width: 34px; height: 34px; flex: none; }\nh1 { font-family: var(--display); font-weight: 400; font-size: clamp(40px, 8vw, 92px); line-height: .9; margin: 0; letter-spacing: -.01em; text-transform: uppercase; text-wrap: balance; }\nh1 span { color: var(--accent); }\n.counter { display: flex; flex-wrap: wrap; gap: 8px; }\n.stat { border: 1px solid var(--line); background: var(--surface); padding: 10px 14px; display: grid; gap: 2px; min-width: 110px; }\n.stat b { font-family: var(--display); font-weight: 400; font-size: 26px; line-height: 1; font-variant-numeric: tabular-nums; }\n.stat small { font-family: var(--mono); font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .08em; }\n.wallet { font-family: var(--mono); font-size: 13px; color: var(--muted); overflow-wrap: anywhere; }\n.wallet a { color: inherit; }\n\n/* Filtres */\n.bar { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 5; background: var(--bg); border-block: 1px solid var(--line); }\n.bar .wrap { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; padding-block: 12px; }\n.seg { display: flex; flex-wrap: wrap; gap: 4px; }\n.seg button { font: 600 13px/1 var(--body); color: var(--fg); background: transparent; border: 1px solid var(--line); padding: 8px 12px; cursor: pointer; }\n.seg button[aria-pressed=\"true\"] { background: var(--accent); border-color: var(--accent); color: var(--chip-fg); }\n.seg button:hover { border-color: var(--accent); }\nselect, input[type=\"search\"] { font: 500 14px/1 var(--body); color: var(--fg); background: var(--surface); border: 1px solid var(--line); padding: 8px 10px; height: 34px; }\ninput[type=\"search\"] { flex: 1 1 180px; min-width: 0; }\n:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n.count { font-family: var(--mono); font-size: 13px; color: var(--muted); margin-left: auto; font-variant-numeric: tabular-nums; }\n\n/* Grille */\nmain { padding-block: 24px 64px; }\n.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 18px 14px; }\n.card { display: grid; gap: 8px; background: none; border: 0; padding: 0; color: inherit; text-align: left; cursor: pointer; font: inherit; }\n.frame { position: relative; aspect-ratio: 214 / 300; max-width: 100%; overflow: hidden; background: var(--surface); border-radius: 6px; transition: transform .25s ease; }\n.frame img { width: 100%; height: 100%; object-fit: contain; display: block; }\n.card:hover .frame, .card:focus-visible .frame { transform: translateY(-4px) rotate(-1deg); }\n.frame.holo::after, .frame.plat::after { content: \"\"; position: absolute; inset: 0; pointer-events: none; mix-blend-mode: color-dodge; opacity: .0; transition: opacity .3s; background: linear-gradient(115deg, transparent 20%, rgba(255,0,200,.55) 36%, rgba(0,230,255,.55) 48%, rgba(255,255,120,.5) 60%, transparent 76%); background-size: 250% 250%; background-position: var(--px, 50%) var(--py, 50%); }\n.frame.plat::after { background: linear-gradient(115deg, transparent 25%, rgba(255,255,255,.7) 45%, transparent 65%); background-size: 250% 250%; background-position: var(--px, 50%) var(--py, 50%); }\n.card:hover .frame.holo::after, .card:hover .frame.plat::after { opacity: .75; }\n.qty { position: absolute; top: 6px; right: 6px; font: 700 12px/1 var(--mono); background: var(--accent); color: #fff; padding: 4px 6px; }\n.meta { display: grid; gap: 2px; min-width: 0; }\n.meta strong { font-weight: 700; font-size: 14px; line-height: 1.25; overflow-wrap: anywhere; }\n.meta span { font-family: var(--mono); font-size: 12px; color: var(--muted); display: flex; gap: 6px; align-items: center; flex-wrap: wrap; }\n.pill { font: 700 11px/1 var(--mono); text-transform: uppercase; letter-spacing: .06em; padding: 3px 5px; border: 1px solid currentColor; }\n.r-C { color: var(--muted); } .r-H { color: var(--holo); } .r-P { color: var(--plat); } .r-W { color: var(--hallo); } .r-K { color: var(--accent); }\n.empty { padding: 48px 0; color: var(--muted); font-family: var(--mono); }\n\n/* Fiche */\ndialog { border: 1px solid var(--line); background: var(--bg); color: var(--fg); padding: 0; max-width: min(760px, calc(100vw - 32px)); width: 100%; }\ndialog::backdrop { background: rgba(5, 6, 8, .78); }\n.sheet { display: grid; grid-template-columns: minmax(0, 300px) minmax(0, 1fr); gap: 24px; padding: 24px; }\n.sheet .frame { cursor: default; }\n.sheet h2 { font-family: var(--display); font-weight: 400; font-size: clamp(28px, 5vw, 40px); line-height: 1; margin: 0 0 16px; text-transform: uppercase; text-wrap: balance; }\n.sheet dl { display: grid; grid-template-columns: auto 1fr; gap: 8px 16px; margin: 0 0 20px; font-size: 14px; }\n.sheet dt { font-family: var(--mono); color: var(--muted); text-transform: uppercase; font-size: 12px; letter-spacing: .08em; padding-top: 2px; }\n.sheet dd { margin: 0; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }\n.sheet a { color: var(--accent); }\n.close { position: absolute; top: 8px; right: 8px; background: var(--surface); border: 1px solid var(--line); color: var(--fg); width: 36px; height: 36px; font-size: 20px; cursor: pointer; }\n.nav { display: flex; gap: 8px; }\n.nav button { font: 600 13px/1 var(--body); background: transparent; color: var(--fg); border: 1px solid var(--line); padding: 9px 12px; cursor: pointer; }\nfooter { border-top: 1px solid var(--line); padding-block: 20px 40px; font-family: var(--mono); font-size: 12px; color: var(--muted); overflow-wrap: anywhere; }\n@media (max-width: 560px) {\n  .grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .sheet { grid-template-columns: 1fr; }\n  .sheet > .frame { max-width: 240px; }\n  .count { margin-left: 0; width: 100%; }\n  .bar { position: static; }\n}\n\n/* Navigation + pages guide */\n.topnav { border-bottom: 1px solid var(--line); background: var(--bg); }\n.topnav .wrap { display: flex; flex-wrap: wrap; gap: 4px 18px; align-items: center; padding-block: 12px; }\n.topnav .tag { font: 700 11px/1 var(--mono); letter-spacing: .1em; text-transform: uppercase; color: var(--muted); margin-right: auto; }\n.topnav a { font: 600 14px/1 var(--body); color: var(--fg); text-decoration: none; padding: 8px 0; border-bottom: 2px solid transparent; }\n.topnav a[aria-current=\"page\"] { border-color: var(--accent); color: var(--accent); }\n.doc { padding-block: 40px 64px; max-width: 820px; }\n.eyebrow { font: 700 12px/1 var(--mono); letter-spacing: .12em; text-transform: uppercase; color: var(--accent); margin: 0 0 12px; }\n.doc-h { font-family: var(--display); font-weight: 400; font-size: clamp(30px, 5.5vw, 52px); line-height: 1; text-transform: uppercase; margin: 0 0 18px; text-wrap: balance; }\n.lede { font-size: 17px; max-width: 65ch; margin: 0 0 24px; }\n.doc p, .doc li { max-width: 68ch; }\n.doc a { color: var(--accent); }\n.doc code { font-family: var(--mono); font-size: .92em; background: var(--surface); border: 1px solid var(--line); padding: 1px 5px; overflow-wrap: anywhere; }\n.warn { border: 1px solid var(--accent); background: var(--accent-soft); padding: 14px 16px; margin: 0 0 32px; max-width: 68ch; }\n.steps { list-style: none; counter-reset: s; padding: 0; margin: 0; display: grid; gap: 34px; }\n.steps > li { counter-increment: s; display: grid; grid-template-columns: 52px minmax(0, 1fr); column-gap: 14px; }\n.steps > li::before { content: counter(s); grid-row: span 9; font-family: var(--display); font-size: 40px; line-height: 1; color: var(--accent); }\n.steps h3 { margin: 4px 0 8px; font-size: 19px; }\n.steps p { margin: 0 0 10px; }\n.steps ul { margin: 0 0 10px; padding-left: 18px; display: grid; gap: 6px; }\n.mini { border-collapse: collapse; margin: 6px 0 12px; font-size: 14px; }\n.mini th, .mini td { border: 1px solid var(--line); padding: 7px 10px; text-align: left; }\n.mini th { font: 700 12px/1.2 var(--mono); text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }\n.note { font-family: var(--mono); font-size: 13px; color: var(--muted); border-top: 1px solid var(--line); padding-top: 14px; margin-top: 36px; }\n.cmds pre, .code { font: 500 13px/1.5 var(--mono); background: var(--surface); border: 1px solid var(--line); padding: 14px; overflow-x: auto; margin: 0 0 16px; }\n.code { max-height: 460px; overflow: auto; white-space: pre; }\n.code.short { max-height: 200px; }\n.codehead { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-top: 18px; font: 700 12px/1 var(--mono); color: var(--muted); }\n.copy { font: 600 13px/1 var(--body); background: var(--accent); color: var(--chip-fg); border: 0; padding: 9px 12px; cursor: pointer; }\n@media (max-width: 560px) { .steps > li { grid-template-columns: 34px minmax(0, 1fr); } .steps > li::before { font-size: 28px; } }\n@media (prefers-reduced-motion: reduce) { .frame, .frame::after { transition: none; } .card:hover .frame { transform: none; } }\n\n.lookup { display: grid; gap: 8px; max-width: 760px; }\n.lab { font: 700 12px/1 var(--mono); letter-spacing: .1em; text-transform: uppercase; color: var(--muted); }\n.lookup .row { display: flex; flex-wrap: wrap; gap: 8px; }\n.lookup input { flex: 1 1 280px; min-width: 0; font: 500 15px/1 var(--mono); color: var(--fg); background: var(--surface); border: 1px solid var(--line); padding: 12px; }\n.go { font: 700 15px/1 var(--body); background: var(--accent); color: var(--chip-fg); border: 0; padding: 12px 18px; cursor: pointer; }\n.hint { margin: 0; font-size: 14px; color: var(--muted); }\n.linkish { background: none; border: 0; padding: 0; font: inherit; color: var(--accent); text-decoration: underline; cursor: pointer; }\n.status { font-family: var(--mono); font-size: 13px; color: var(--muted); margin: 0; min-height: 1.2em; overflow-wrap: anywhere; }\n.status a, .empty a, footer a { color: var(--accent); }\n.dl { font: 600 13px/1 var(--body); color: var(--fg); border: 1px solid var(--line); padding: 9px 12px; text-decoration: none; }\n.empty { max-width: 65ch; font-family: var(--body); line-height: 1.6; }\n</style><style>body{margin:0}img{max-width:100%}[hidden]{display:none!important}</style></head><body><nav class=\"topnav\" aria-label=\"Sections\"><div class=\"wrap\"><span class=\"tag\">Rules Rescue \u00b7 archive non officielle</span><a href=\"#explorer\">Explorer</a><a href=\"#tuto\">Guide de r\u00e9cup\u00e9ration</a><a href=\"#outil\">Outil</a></div></nav>\n\n<section class=\"view\" data-view=\"explorer\">\n<header class=\"wrap\">\n  <div class=\"brand\">Cartes Rules TCG \u00b7 Starknet \u00b7 lecture seule</div>\n  <h1>O\u00f9 sont<br>mes <span>cartes</span>&nbsp;?</h1>\n  <form id=\"f\" class=\"lookup\" autocomplete=\"off\">\n    <label for=\"addr\" class=\"lab\">Adresse Starknet (0x\u2026)</label>\n    <div class=\"row\">\n      <input id=\"addr\" name=\"addr\" type=\"text\" inputmode=\"text\" spellcheck=\"false\" placeholder=\"0x0\u2026 ton wallet Argent/Ready/Braavos ou ton ancien compte Rules\" required>\n      <button type=\"submit\" class=\"go\">Voir les cartes</button>\n    </div>\n    <p class=\"hint\">Rien \u00e0 connecter, aucune signature : la page lit seulement la blockchain publique. <button type=\"button\" class=\"linkish\" id=\"demo\">Essayer avec une collection d'exemple</button></p>\n  </form>\n  <div class=\"counter\" id=\"stats\"></div>\n  <p class=\"status\" id=\"status\" role=\"status\"></p>\n</header>\n\n<div class=\"bar\" id=\"bar\" hidden>\n  <div class=\"wrap\">\n    <div class=\"seg\" id=\"kind\" role=\"group\" aria-label=\"Type\">\n      <button type=\"button\" data-v=\"all\" aria-pressed=\"true\">Tout</button>\n      <button type=\"button\" data-v=\"card\" aria-pressed=\"false\">Cartes</button>\n      <button type=\"button\" data-v=\"pack\" aria-pressed=\"false\">Packs</button>\n    </div>\n    <div class=\"seg\" id=\"rar\" role=\"group\" aria-label=\"Raret\u00e9\">\n      <button type=\"button\" data-v=\"all\" aria-pressed=\"true\">Toutes</button>\n      <button type=\"button\" data-v=\"H\" aria-pressed=\"false\">Holo</button>\n      <button type=\"button\" data-v=\"P\" aria-pressed=\"false\">Platinium</button>\n      <button type=\"button\" data-v=\"W\" aria-pressed=\"false\">Halloween</button>\n      <button type=\"button\" data-v=\"C\" aria-pressed=\"false\">Common</button>\n    </div>\n    <select id=\"season\" aria-label=\"Saison\"><option value=\"all\">Saisons 1 + 2</option><option value=\"1\">Saison 1</option><option value=\"2\">Saison 2</option></select>\n    <select id=\"artist\" aria-label=\"Artiste\"><option value=\"all\">Tous les artistes</option></select>\n    <select id=\"sort\" aria-label=\"Tri\"><option value=\"rar\">Tri : raret\u00e9</option><option value=\"artist\">Tri : artiste</option><option value=\"serial\">Tri : n\u00b0 de s\u00e9rie</option></select>\n    <a class=\"dl\" id=\"dl\" href=\"#\">cartes.json</a>\n    <div class=\"count\" id=\"count\"></div>\n  </div>\n</div>\n\n<main class=\"wrap\">\n  <div class=\"grid\" id=\"grid\"></div>\n  <div class=\"empty\" id=\"empty\" hidden></div>\n</main>\n\n<footer class=\"wrap\">Donn\u00e9es lues sur Starknet via l'explorateur Voyager (contrat des cartes 0x05b456031650c1de9eec123d3e7d06a684d321a346d4a7cac9fd86c2b77cf70f). Site non officiel, sans lien avec Rules Labs. Les illustrations appartiennent \u00e0 leurs artistes.</footer>\n</section>\n\n<section class=\"view wrap doc\" data-view=\"tuto\" hidden>\n  <p class=\"hint\" style=\"margin-bottom:18px\">Commence par l'onglet <a href=\"#explorer\">Explorer</a> : colle une adresse et vois si des cartes y sont.</p>\n  <p class=\"eyebrow\">Guide \u00b7 ancien utilisateur Rules</p>\n  <h2 class=\"doc-h\">R\u00e9cup\u00e9rer ses cartes Rules apr\u00e8s la fermeture</h2>\n  <p class=\"lede\">Rules (rules.art) a ferm\u00e9, mais les cartes sont des NFT sur Starknet et elles y sont toujours. Si ton wallet ne les montre pas, ce guide retrace la d\u00e9marche qui a march\u00e9 pour une collection de 250 cartes. Compte une heure, et quelques centimes de frais r\u00e9seau \u00e0 la fin.</p>\n\n  <div class=\"warn\"><b>R\u00e8gle n\u00b01.</b> Ta seed phrase (12 ou 24 mots) ne se colle sur aucun site, dans aucun formulaire de support, dans aucun chat. Personne de l\u00e9gitime ne te la demandera. Tout ce qui suit se fait en local sur ta machine.</div>\n\n  <ol class=\"steps\">\n    <li>\n      <h3>Comprendre o\u00f9 sont parties tes cartes</h3>\n      <p>Fin 2023, Rules a propos\u00e9 une migration : on connectait une extension <b>Argent X</b> ou <b>Braavos</b>, et le site transf\u00e9rait les cartes vers le compte actif de cette extension. Le code public de l'interface (d\u00e9p\u00f4t <code>ruleslabs/interface</code>, fichier <code>MigrateCollectionModal/Cards.tsx</code>) le confirme : la destination est l'adresse du wallet connect\u00e9, sans saisie manuelle possible.</p>\n      <p>Donc tes cartes sont sur l'adresse Starknet de ton extension de l'\u00e9poque, pas sur ton compte Rules, ni sur MetaMask, ni sur Argent Vault (qui est un wallet Ethereum).</p>\n    </li>\n    <li>\n      <h3>Retrouver l'adresse qui d\u00e9tient les cartes</h3>\n      <p>Pars d'une adresse que tu connais (MetaMask, ancien compte Rules) et remonte la piste sur l'explorateur <a href=\"https://voyager.online\" target=\"_blank\" rel=\"noopener\">voyager.online</a> :</p>\n      <ul>\n        <li>Une adresse MetaMask a souvent un d\u00e9p\u00f4t <em>StarkGate</em> vers Starknet. Le champ <code>l2Recipient</code> de cette transaction sur Etherscan donne ton ancien compte Rules.</li>\n        <li>Sur Voyager, ouvre ce compte, onglet <em>Transactions</em> : un gros <code>batch_transfer_from</code> fin 2023 ou en 2024 montre vers quelle adresse les cartes sont parties.</li>\n        <li>Sur cette adresse de destination, les cartes du contrat <code>0x05b4\u2026f70f</code> (le contrat des cartes Rules) apparaissent dans les transferts NFT.</li>\n      </ul>\n      <p>Si Voyager affiche \u00ab Contract not found \u00bb pour cette adresse, c'est normal : le compte a re\u00e7u les cartes mais n'a jamais \u00e9t\u00e9 <b>d\u00e9ploy\u00e9</b>.</p>\n    </li>\n    <li>\n      <h3>Comprendre pourquoi ton wallet ne l'affiche pas</h3>\n      <p>Une adresse Starknet est calcul\u00e9e \u00e0 partir de ta cl\u00e9 <b>et</b> de la version du contrat de compte. En novembre 2023, Argent X utilisait la version 0.3.0. Ready (le nouveau nom d'Argent) utilise aujourd'hui une version plus r\u00e9cente. Avec la m\u00eame seed, il calcule donc une autre adresse et ne retrouve pas tout seul l'ancienne si elle n'a jamais servi.</p>\n      <table class=\"mini\">\n        <thead><tr><th>M\u00eame seed, compte n\u00b00</th><th>Adresse</th></tr></thead>\n        <tbody>\n          <tr><td>Argent X v0.3.0 (fin 2023)</td><td>celle qui d\u00e9tient les cartes</td></tr>\n          <tr><td>Ready v0.4.0 (aujourd'hui)</td><td>celle que l'app affiche</td></tr>\n        </tbody>\n      </table>\n      <p>Braavos et MetaMask ne peuvent pas ouvrir ce compte : ils calculent leurs adresses autrement.</p>\n    </li>\n    <li>\n      <h3>Retrouver la bonne seed</h3>\n      <p>La seed est celle de l'extension utilis\u00e9e pendant la migration. Si tu utilises encore Ready sur le m\u00eame ordinateur, c'est souvent la m\u00eame. Sinon, cherche dans tes notes (Google Keep, Notes), tes captures d'\u00e9cran, un papier, un gestionnaire de mots de passe. Une vraie seed fait 12 ou 24 mots de la <a href=\"https://github.com/bitcoin/bips/blob/master/bip-0039/english.txt\" target=\"_blank\" rel=\"noopener\">liste BIP39</a> et a une somme de contr\u00f4le valide.</p>\n      <p>Pour v\u00e9rifier sans risque, restaure la seed dans un <b>profil de navigateur vierge</b> (jamais via \u00ab Mot de passe oubli\u00e9 \u00bb dans ton wallet actuel, qui l'effacerait) et compare les adresses. Le script de l'onglet <a href=\"#outil\">Outil</a> fait ce test hors ligne, sur toutes les versions d'Argent connues.</p>\n    </li>\n    <li>\n      <h3>Pr\u00e9venir le support Ready</h3>\n      <p>Le support passe par le formulaire de <a href=\"https://help.ready.co/hc/en-us/requests/new\" target=\"_blank\" rel=\"noopener\">help.ready.co</a> (choisir \u00ab Ready X (previously Argent X) \u00bb). Donne l'adresse des cartes, la version du compte (0.3.0), l'index (souvent 0) et ton adresse Ready actuelle. Le formulaire demande ensuite de confirmer ton email avant d'envoyer la demande.</p>\n    </li>\n    <li>\n      <h3>D\u00e9ployer le compte et rapatrier les cartes</h3>\n      <p>Si le support ne r\u00e8gle pas le probl\u00e8me, le script de l'onglet <a href=\"#outil\">Outil</a> le fait en trois temps : <code>find</code> retrouve le compte \u00e0 partir de la seed, <code>check</code> v\u00e9rifie son \u00e9tat sur la cha\u00eene, <code>migrate</code> simule le d\u00e9ploiement et le transfert, et n'envoie rien tant que tu n'ajoutes pas <code>--execute</code> et que tu ne tapes pas OUI.</p>\n      <p>Il faut un peu de <b>STRK</b> sur l'adresse des cartes pour payer les frais : la simulation donne le montant exact, en g\u00e9n\u00e9ral bien moins d'un euro.</p>\n    </li>\n    <li>\n      <h3>S\u00e9curiser ensuite</h3>\n      <ul>\n        <li>Envoie les cartes vers un <b>wallet neuf</b> (Braavos ou Ready) dont la seed n'a jamais \u00e9t\u00e9 tap\u00e9e ailleurs que sur papier.</li>\n        <li>Supprime toute seed stock\u00e9e en clair dans le cloud (notes, mails, captures).</li>\n        <li>M\u00e9fie-toi des messages qui proposent de \u00ab r\u00e9cup\u00e9rer tes NFT Rules \u00bb : c'est presque toujours une arnaque.</li>\n      </ul>\n    </li>\n  </ol>\n  <p class=\"note\">Statut : les \u00e9tapes 1 \u00e0 5 ont \u00e9t\u00e9 suivies jusqu'au bout. L'\u00e9tape 6 a \u00e9t\u00e9 simul\u00e9e sans envoi. Une simulation sur Starknet mainnet (octobre 2026) confirme qu'un compte v0.3.0 se d\u00e9ploie encore et que le transfert passe : environ 0,03 STRK pour le d\u00e9ploiement et 0,06 STRK par lot de cartes.</p>\n</section>\n\n<section class=\"view wrap doc\" data-view=\"outil\" hidden>\n  <p class=\"eyebrow\">Outil \u00b7 Python, en local</p>\n  <h2 class=\"doc-h\">rules_rescue.py</h2>\n  <p class=\"lede\">Retrouve l'ancien compte Argent X qui d\u00e9tient tes cartes, puis simule et ex\u00e9cute leur transfert vers un wallet de ton choix. La seed est saisie de fa\u00e7on masqu\u00e9e, n'est jamais \u00e9crite sur le disque et ne part pas sur le r\u00e9seau.</p>\n  <div class=\"cmds\">\n    <pre><code>pip install starknet-py\npython rules_rescue.py find    --target 0xADRESSE_DES_CARTES\npython rules_rescue.py check   --target 0xADRESSE_DES_CARTES\npython rules_rescue.py migrate --target 0xADRESSE_DES_CARTES --to 0xNOUVEAU_WALLET --ids cartes.json\npython rules_rescue.py migrate --target 0xADRESSE_DES_CARTES --to 0xNOUVEAU_WALLET --ids cartes.json --execute</code></pre>\n  </div>\n  <p><a class=\"dl\" href=\"/rules_rescue.py\">T\u00e9l\u00e9charger rules_rescue.py</a></p><p><code>cartes.json</code> est la liste des cartes \u00e0 transf\u00e9rer, au format <code>[{\"id\": \"\u2026\", \"q\": 1}]</code>.</p>\n  \n  <p>Ta propre liste <code>cartes.json</code> se t\u00e9l\u00e9charge depuis l'onglet <a href=\"#explorer\">Explorer</a>, une fois ton adresse affich\u00e9e (bouton \u00ab cartes.json \u00bb).</p>\n</section>\n\n\n\n\n\n<dialog id=\"dlg\" aria-label=\"D\u00e9tail de la carte\">\n  <button class=\"close\" id=\"dlgClose\" type=\"button\" aria-label=\"Fermer\">\u00d7</button>\n  <div class=\"sheet\" id=\"sheet\"></div>\n</dialog>\n\n<script>\nconst CONTRACT = \"0x05b456031650c1de9eec123d3e7d06a684d321a346d4a7cac9fd86c2b77cf70f\";\nconst DEMO = \"0x079be38babc015722dacfe6a741219540688bc988319879851e2062dc25319cf\";\nconst RN = { C: \"Common\", H: \"Holographic\", P: \"Platinium\", W: \"Halloween\", K: \"Pack\" };\nconst RORD = { P: 0, H: 1, W: 2, C: 3, K: 4 };\nconst $ = id => document.getElementById(id);\nlet items = [], view = [], cur = 0;\nconst state = { kind: \"all\", rar: \"all\", season: \"all\", artist: \"all\", sort: \"rar\" };\nfunction esc(s) { return String(s).replace(/[&<>\"]/g, c => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" }[c])); }\n\nfunction normAddr(a) {\n  a = a.trim().toLowerCase();\n  if (!/^0x[0-9a-f]{1,64}$/.test(a)) return null;\n  return \"0x\" + a.slice(2).padStart(64, \"0\");\n}\n\nasync function load(addr) {\n  $(\"status\").textContent = \"Lecture de la blockchain\u2026 (jusqu'\u00e0 30 s pour une grosse collection)\";\n  $(\"grid\").innerHTML = \"\"; $(\"stats\").innerHTML = \"\"; $(\"bar\").hidden = true; $(\"empty\").hidden = true;\n  try {\n    const r = await fetch(\"/api/cards?address=\" + addr);\n    const j = await r.json();\n    if (!r.ok) throw new Error(j.error || r.status);\n    items = j.items.map((d, i) => ({ ...d, i }));\n    $(\"dl\").href = \"/api/cards?address=\" + addr + \"&format=ids\";\n    const deployed = j.deployed ? \"d\u00e9ploy\u00e9\" : \"jamais d\u00e9ploy\u00e9 (normal pour un compte de migration Rules)\";\n    $(\"status\").innerHTML = items.length\n      ? `Compte <a href=\"https://voyager.online/contract/${addr}\" target=\"_blank\" rel=\"noopener\">${addr.slice(0, 8)}\u2026${addr.slice(-6)}</a> \u00b7 ${deployed}.`\n      : \"\";\n    if (!items.length) {\n      $(\"empty\").hidden = false;\n      $(\"empty\").innerHTML = `<b>Aucune carte Rules sur cette adresse.</b> Si c'est ton ancien compte Rules, ouvre-le sur <a href=\"https://voyager.online/contract/${addr}\" target=\"_blank\" rel=\"noopener\">Voyager</a> et cherche un gros transfert de cartes fin 2023 : l'adresse de destination est celle de ton wallet de migration. Le <a href=\"#tuto\">guide</a> explique la marche \u00e0 suivre.`;\n      return;\n    }\n    stats(); fillArtists(); $(\"bar\").hidden = false; render();\n  } catch (e) {\n    $(\"status\").textContent = \"Lecture impossible pour l'instant (\" + e.message + \"). R\u00e9essaie dans une minute.\";\n  }\n}\n\nfunction stats() {\n  const cards = items.filter(d => d.r !== \"K\");\n  const st = [\n    [cards.reduce((s, d) => s + d.q, 0), \"cartes\"],\n    [items.filter(d => d.r === \"K\").reduce((s, d) => s + d.q, 0), \"packs\"],\n    [new Set(cards.map(d => d.a)).size, \"artistes\"],\n    [cards.filter(d => d.r === \"H\").length, \"holo\"],\n    [cards.filter(d => d.r === \"P\").length, \"platinium\"],\n  ];\n  $(\"stats\").innerHTML = st.map(([n, l]) => `<div class=\"stat\"><b>${n}</b><small>${l}</small></div>`).join(\"\");\n}\nfunction fillArtists() {\n  const counts = {}; items.filter(d => d.r !== \"K\").forEach(d => counts[d.a] = (counts[d.a] || 0) + d.q);\n  $(\"artist\").innerHTML = `<option value=\"all\">Tous les artistes</option>` + Object.keys(counts).sort((a, b) => a.localeCompare(b, \"fr\")).map(a => `<option value=\"${esc(a)}\">${esc(a)} (${counts[a]})</option>`).join(\"\");\n  state.artist = \"all\";\n}\nfunction filtered() {\n  const out = items.filter(d =>\n    (state.kind === \"all\" || (state.kind === \"pack\") === (d.r === \"K\")) &&\n    (state.rar === \"all\" || d.r === state.rar) &&\n    (state.season === \"all\" || String(d.s) === state.season) &&\n    (state.artist === \"all\" || d.a === state.artist));\n  const by = {\n    rar: (x, y) => RORD[x.r] - RORD[y.r] || x.a.localeCompare(y.a, \"fr\") || x.n - y.n,\n    artist: (x, y) => (x.r === \"K\") - (y.r === \"K\") || x.a.localeCompare(y.a, \"fr\") || x.n - y.n,\n    serial: (x, y) => (x.r === \"K\") - (y.r === \"K\") || x.n - y.n,\n  }[state.sort];\n  return out.sort(by);\n}\nfunction frameCls(d) { return d.r === \"H\" ? \"holo\" : d.r === \"P\" ? \"plat\" : \"\"; }\nfunction render() {\n  view = filtered();\n  $(\"grid\").innerHTML = view.map((d, k) => `\n    <button class=\"card\" type=\"button\" data-k=\"${k}\">\n      <div class=\"frame ${frameCls(d)}\">\n        <img src=\"/img/${d.id}\" alt=\"${esc(d.r === \"K\" ? d.a : d.a + \" \" + RN[d.r] + \" n\u00b0\" + d.n)}\" loading=\"lazy\" decoding=\"async\">\n        ${d.q > 1 ? `<span class=\"qty\">\u00d7${d.q}</span>` : \"\"}\n      </div>\n      <div class=\"meta\"><strong>${esc(d.a)}</strong><span><em class=\"pill r-${d.r}\">${RN[d.r]}</em>${d.r === \"K\" ? \"\" : \"#\" + d.n + \" \u00b7\"} S${d.s}</span></div>\n    </button>`).join(\"\");\n  $(\"count\").textContent = `${view.length} / ${items.length}`;\n  for (const id of [\"kind\", \"rar\"]) document.querySelectorAll(`#${id} button`).forEach(b => b.setAttribute(\"aria-pressed\", String(b.dataset.v === state[id])));\n}\nfor (const id of [\"kind\", \"rar\"]) $(id).addEventListener(\"click\", e => { const b = e.target.closest(\"button\"); if (!b) return; state[id] = b.dataset.v; render(); });\nfor (const id of [\"season\", \"artist\", \"sort\"]) $(id).addEventListener(\"change\", e => { state[id] = e.target.value; render(); });\n$(\"grid\").addEventListener(\"pointermove\", e => {\n  const f = e.target.closest(\".frame\"); if (!f) return; const r = f.getBoundingClientRect();\n  f.style.setProperty(\"--px\", ((e.clientX - r.left) / r.width * 100) + \"%\"); f.style.setProperty(\"--py\", ((e.clientY - r.top) / r.height * 100) + \"%\");\n});\nfunction openAt(k) {\n  cur = (k + view.length) % view.length; const d = view[cur];\n  $(\"sheet\").innerHTML = `\n    <div class=\"frame ${frameCls(d)}\"><img src=\"/img/${d.id}\" alt=\"\"></div>\n    <div><h2>${esc(d.a)}</h2><dl>\n      <dt>Raret\u00e9</dt><dd><span class=\"pill r-${d.r}\">${RN[d.r]}</span></dd>\n      ${d.r === \"K\" ? \"\" : `<dt>N\u00b0 de s\u00e9rie</dt><dd>#${d.n}</dd>`}\n      <dt>Saison</dt><dd>${d.s}</dd><dt>Exemplaires</dt><dd>${d.q}</dd>\n      <dt>Token</dt><dd><a href=\"https://voyager.online/nft/${CONTRACT}/${d.id}\" target=\"_blank\" rel=\"noopener\">Voir sur Voyager \u2197</a></dd>\n    </dl><div class=\"nav\"><button type=\"button\" id=\"prev\">\u2190 Pr\u00e9c\u00e9dente</button><button type=\"button\" id=\"next\">Suivante \u2192</button></div></div>`;\n  $(\"prev\").onclick = () => openAt(cur - 1); $(\"next\").onclick = () => openAt(cur + 1);\n  if (!$(\"dlg\").open) $(\"dlg\").showModal();\n}\n$(\"grid\").addEventListener(\"click\", e => { const c = e.target.closest(\".card\"); if (c) openAt(+c.dataset.k); });\n$(\"dlgClose\").onclick = () => $(\"dlg\").close();\n$(\"dlg\").addEventListener(\"click\", e => { if (e.target === $(\"dlg\")) $(\"dlg\").close(); });\ndocument.addEventListener(\"keydown\", e => { if (!$(\"dlg\").open) return; if (e.key === \"ArrowRight\") openAt(cur + 1); if (e.key === \"ArrowLeft\") openAt(cur - 1); });\n\n$(\"f\").addEventListener(\"submit\", e => {\n  e.preventDefault(); const a = normAddr($(\"addr\").value);\n  if (!a) { $(\"status\").textContent = \"Adresse invalide : elle doit commencer par 0x et ne contenir que des caract\u00e8res 0-9 et a-f.\"; return; }\n  history.replaceState(null, \"\", \"?address=\" + a + location.hash); load(a);\n});\n$(\"demo\").onclick = () => { $(\"addr\").value = DEMO; $(\"f\").requestSubmit(); };\n\nfunction route() {\n  const v = [\"explorer\", \"tuto\", \"outil\"].includes(location.hash.slice(1)) ? location.hash.slice(1) : \"explorer\";\n  document.querySelectorAll(\".view\").forEach(s => s.hidden = s.dataset.view !== v);\n  document.querySelectorAll(\".topnav a\").forEach(a => a.setAttribute(\"aria-current\", a.getAttribute(\"href\") === \"#\" + v ? \"page\" : \"false\"));\n}\naddEventListener(\"hashchange\", route); route();\ndocument.querySelectorAll(\".copy\").forEach(b => b.addEventListener(\"click\", async () => {\n  const el = $(b.dataset.copy);\n  try { await navigator.clipboard.writeText(el.textContent); b.textContent = \"Copi\u00e9\"; }\n  catch (e) { const r = document.createRange(); r.selectNodeContents(el); const s = getSelection(); s.removeAllRanges(); s.addRange(r); b.textContent = \"S\u00e9lectionn\u00e9, fais Ctrl+C\"; }\n}));\nconst q = new URLSearchParams(location.search).get(\"address\");\nif (q && normAddr(q)) { $(\"addr\").value = normAddr(q); load(normAddr(q)); }\n</script>\n</body></html>";
const SCRIPT = "#!/usr/bin/env python3\n\"\"\"\nrules_rescue.py \u2014 r\u00e9cup\u00e9rer des cartes Rules (Starknet) bloqu\u00e9es sur un ancien\ncompte Argent X jamais d\u00e9ploy\u00e9.\n\nTout tourne sur TA machine. La seed est demand\u00e9e de fa\u00e7on masqu\u00e9e, n'est jamais\n\u00e9crite sur le disque ni envoy\u00e9e sur le r\u00e9seau : seuls des appels RPC publics en\nlecture (et, en mode --execute uniquement, des transactions SIGN\u00c9ES) partent.\n\nInstallation :\n    pip install starknet-py\n\n\u00c9tapes :\n    1) find      \u2192 retrouve quel compte (index + version Argent) correspond \u00e0 l'adresse des cartes\n    2) check     \u2192 v\u00e9rifie l'\u00e9tat on-chain (classe d\u00e9clar\u00e9e, d\u00e9ploy\u00e9 ou non, solde STRK/ETH)\n    3) migrate   \u2192 SIMULE le d\u00e9ploiement + le transfert des cartes (rien n'est envoy\u00e9)\n    4) migrate --execute \u2192 envoie vraiment, apr\u00e8s confirmation tap\u00e9e \u00e0 la main\n\nExemples :\n    python rules_rescue.py find  --target 0x079be...\n    python rules_rescue.py check --target 0x079be...\n    python rules_rescue.py migrate --target 0x079be... --to 0xTON_NOUVEAU_WALLET --ids cartes.json\n    python rules_rescue.py migrate --target 0x079be... --to 0x... --ids cartes.json --execute\n\"\"\"\nimport argparse, asyncio, getpass, hashlib, hmac, json, sys, unicodedata\n\nfrom starknet_py.hash.address import compute_address\nfrom starknet_py.hash.selector import get_selector_from_name\nfrom starknet_py.net.signer.key_pair import KeyPair\nfrom starknet_py.net.full_node_client import FullNodeClient\nfrom starknet_py.net.account.account import Account\nfrom starknet_py.net.models import StarknetChainId\nfrom starknet_py.net.client_models import Call, ResourceBounds, ResourceBoundsMapping\n\nRULES_CARDS = 0x05B456031650C1DE9EEC123D3E7D06A684D321A346D4A7CAC9FD86C2B77CF70F\nSTRK = 0x04718F5A0FC34CC1AF16A1CDEE98FFB20C31F5CD61D6AB07201858F4287C938D\nETH = 0x049D36570D4E46F48E99674BD3FCC84644DDD6B96F7C741B1562B82F9E004DC7\nRPCS = [\n    \"https://api.zan.top/public/starknet-mainnet\",\n    \"https://starknet-mainnet.public.blastapi.io/rpc/v0_8\",\n    \"https://free-rpc.nethermind.io/mainnet-juno/v0_8\",\n    \"https://rpc.starknet.lava.build\",\n    \"https://starknet.drpc.org\",\n]\n\n# --- Types de comptes Argent / Braavos connus (classe + calldata du constructeur) ---\nPROXY = 0x25EC026985A3BF9D0CC1FE17326B245DFDC3FF89B8FDE106542A3EA56C5A918\nINIT = get_selector_from_name(\"initialize\")\nTYPES = {\n    \"argent-cairo0-0.2.3\":   (\"proxy\", 0x33434AD846CDD5F23EB73FF09FE6FDDD568284A0FB7D1BE20EE482F044DABE2),\n    \"argent-cairo0-0.2.3.1\": (\"proxy\", 0x1A7820094FEAF82D53F53F214B81292D717E7BB9A92BB2488092CD306F3993F),\n    \"argent-cairo0-0.2.2\":   (\"proxy\", 0x3E327DE1C40540B98D05CBCB13552008E36F0EC8D61D46956D2F9752C294328),\n    \"argent-cairo0-old\":     (\"proxy\", 0x90AA7A9203BFF78BFB24F0753C180A33D4BAD95B1F4F510B36B00993815704),\n    \"argent-0.3.0\":          (\"c1\",    0x1A736D6ED154502257F02B1CCDF4D9D1089F80811CD6ACAD48E6B6A9D1F2003),\n    \"argent-0.3.1\":          (\"c1\",    0x29927C8AF6BCCF3F6FDA035981E765A7BDBF18A2DC0D630494F8758AA908E2B),\n    \"argent-0.4.0 (Ready)\":  (\"v4\",    0x036078334509B514626504EDC9FB252328D1A240E4E948BEF8D0C08DFF45927F),\n}\n\ndef deploy_params(kind, ch, pk):\n    if kind == \"proxy\":\n        return PROXY, [ch, INIT, 2, pk, 0]\n    if kind == \"c1\":\n        return ch, [pk, 0]\n    return ch, [0, pk, 1]\n\n# --- D\u00e9rivation de cl\u00e9 fa\u00e7on Argent X (BIP39 \u2192 cl\u00e9 ETH \u2192 HD Starknet \u2192 grind) ---\nP = 2**256 - 2**32 - 977\nN = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141\nG = (0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798,\n     0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8)\nSN_ORDER = 0x0800000000000010FFFFFFFFFFFFFFFFB781126DCAE7B2321E66A241ADC64D2F\n\ndef _add(a, b):\n    if a is None: return b\n    if b is None: return a\n    if a[0] == b[0] and (a[1] + b[1]) % P == 0: return None\n    l = ((3 * a[0] * a[0]) * pow(2 * a[1], -1, P) if a == b else (b[1] - a[1]) * pow(b[0] - a[0], -1, P)) % P\n    x = (l * l - a[0] - b[0]) % P\n    return (x, (l * (a[0] - x) - a[1]) % P)\n\ndef _mul(k, p=G):\n    r = None\n    while k:\n        if k & 1: r = _add(r, p)\n        p = _add(p, p); k >>= 1\n    return r\n\ndef _derive(seed, path):\n    I = hmac.new(b\"Bitcoin seed\", seed, hashlib.sha512).digest()\n    k, c = int.from_bytes(I[:32], \"big\"), I[32:]\n    for part in path.split(\"/\")[1:]:\n        h = part.endswith(\"'\"); i = int(part.rstrip(\"'\")) + (0x80000000 if h else 0)\n        if h: data = b\"\\0\" + k.to_bytes(32, \"big\") + i.to_bytes(4, \"big\")\n        else:\n            pt = _mul(k); data = bytes([2 + (pt[1] & 1)]) + pt[0].to_bytes(32, \"big\") + i.to_bytes(4, \"big\")\n        I = hmac.new(c, data, hashlib.sha512).digest()\n        k, c = (int.from_bytes(I[:32], \"big\") + k) % N, I[32:]\n    return k\n\ndef _grind(key):\n    lim = 2**256 - (2**256 % SN_ORDER); kb = key.to_bytes(32, \"big\"); i = 0\n    while True:\n        h = int.from_bytes(hashlib.sha256(kb + i.to_bytes(1 if i < 256 else 2, \"big\")).digest(), \"big\")\n        if h < lim: return h % SN_ORDER\n        i += 1\n\ndef argentx_key(mnemonic, index):\n    m = unicodedata.normalize(\"NFKD\", \" \".join(mnemonic.lower().split()))\n    seed = hashlib.pbkdf2_hmac(\"sha512\", m.encode(), b\"mnemonic\", 2048)\n    eth = _derive(seed, \"m/44'/60'/0'/0/0\")\n    h = hex(eth)[2:]; h = h if len(h) % 2 == 0 else \"0\" + h\n    return _grind(_derive(bytes.fromhex(h), f\"m/44'/9004'/0'/0/{index}\"))\n\ndef ask_seed():\n    s = getpass.getpass(\"Seed (12/24 mots, saisie masqu\u00e9e) : \")\n    if len(s.split()) not in (12, 15, 18, 21, 24):\n        sys.exit(\"Nombre de mots invalide.\")\n    return s\n\ndef find_account(mnemonic, target, max_index=20):\n    for i in range(max_index):\n        sk = argentx_key(mnemonic, i); pk = KeyPair.from_private_key(sk).public_key\n        for name, (kind, ch) in TYPES.items():\n            cls, cd = deploy_params(kind, ch, pk)\n            if compute_address(class_hash=cls, constructor_calldata=cd, salt=pk, deployer_address=0) == target:\n                return i, name, sk, pk, cls, cd\n    return None\n\nasync def get_client(rpc):\n    for url in ([rpc] if rpc else RPCS):\n        try:\n            c = FullNodeClient(node_url=url); await c.get_block_number(); return c, url\n        except Exception as e:\n            print(f\"  RPC indisponible : {url} ({type(e).__name__})\")\n    sys.exit(\"Aucun RPC joignable. Passe --rpc <url> (Alchemy, Infura, Nethermind\u2026).\")\n\nasync def balance(client, token, addr):\n    r = await client.call_contract(Call(to_addr=token, selector=get_selector_from_name(\"balance_of\"), calldata=[addr]))\n    return r[0] + (r[1] << 128 if len(r) > 1 else 0)\n\ndef u256(x): return [x & ((1 << 128) - 1), x >> 128]\n\ndef load_ids(path):\n    data = json.load(open(path, encoding=\"utf-8\"))\n    return [(int(d[\"id\"]), int(d.get(\"q\", 1))) for d in data]\n\ndef transfer_calls(frm, to, items, chunk=40):\n    sel = get_selector_from_name(\"batch_transfer_from\")\n    calls = []\n    for k in range(0, len(items), chunk):\n        part = items[k:k + chunk]\n        cd = [frm, to, len(part)]\n        for i, _ in part: cd += u256(i)\n        cd.append(len(part))\n        for _, q in part: cd += u256(q)\n        calls.append(Call(to_addr=RULES_CARDS, selector=sel, calldata=cd))\n    return calls\n\nBIG = ResourceBoundsMapping(\n    l1_gas=ResourceBounds(max_amount=10**5, max_price_per_unit=10**14),\n    l1_data_gas=ResourceBounds(max_amount=10**5, max_price_per_unit=10**14),\n    l2_gas=ResourceBounds(max_amount=10**9, max_price_per_unit=10**11),\n)\n\nasync def main():\n    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)\n    ap.add_argument(\"cmd\", choices=[\"find\", \"check\", \"migrate\"])\n    ap.add_argument(\"--target\", required=True, help=\"adresse qui d\u00e9tient les cartes\")\n    ap.add_argument(\"--to\", help=\"wallet de destination (migrate)\")\n    ap.add_argument(\"--ids\", help=\"fichier JSON [{id, q}] des cartes (migrate)\")\n    ap.add_argument(\"--rpc\", help=\"URL RPC Starknet mainnet\")\n    ap.add_argument(\"--execute\", action=\"store_true\", help=\"envoyer vraiment (sinon simulation)\")\n    a = ap.parse_args()\n    target = int(a.target, 16)\n\n    if a.cmd == \"check\":\n        client, url = await get_client(a.rpc); print(\"RPC :\", url)\n        try:\n            ch = await client.get_class_hash_at(target); print(\"Compte D\u00c9PLOY\u00c9, classe\", hex(ch))\n        except Exception:\n            print(\"Compte NON d\u00e9ploy\u00e9 (normal pour un compte de migration Rules).\")\n        for name, (kind, ch) in TYPES.items():\n            try: await client.get_class_by_hash(ch); ok = \"d\u00e9clar\u00e9e\"\n            except Exception: ok = \"INTROUVABLE\"\n            print(f\"  classe {name:24s} {ok}\")\n        print(\"Solde STRK :\", (await balance(client, STRK, target)) / 1e18)\n        print(\"Solde ETH  :\", (await balance(client, ETH, target)) / 1e18)\n        return\n\n    mnemonic = ask_seed()\n    print(\"Recherche du compte (calcul local, ~30 s)\u2026\")\n    hit = find_account(mnemonic, target)\n    del mnemonic\n    if not hit:\n        sys.exit(\"Aucun compte Argent X (index 0\u201319) de cette seed ne donne cette adresse.\")\n    idx, name, sk, pk, cls, cd = hit\n    print(f\"Trouv\u00e9 : compte n\u00b0{idx}, type {name}.\")\n    if a.cmd == \"find\":\n        return\n\n    if not a.to or not a.ids:\n        sys.exit(\"migrate demande --to et --ids.\")\n    to = int(a.to, 16)\n    items = load_ids(a.ids)\n    print(f\"{len(items)} objets ({sum(q for _, q in items)} exemplaires) \u2192 {hex(to)}\")\n    client, url = await get_client(a.rpc); print(\"RPC :\", url)\n    kp = KeyPair.from_private_key(sk)\n    acc = Account(address=target, client=client, key_pair=kp, chain=StarknetChainId.MAINNET)\n    try:\n        await client.get_class_hash_at(target); deployed = True\n    except Exception:\n        deployed = False\n    calls = transfer_calls(target, to, items)\n\n    if not a.execute:\n        txs, nonce = [], 0\n        if not deployed:\n            txs.append(await acc.sign_deploy_account_v3(class_hash=cls, contract_address_salt=pk,\n                                                       constructor_calldata=cd, nonce=0, resource_bounds=BIG))\n            nonce = 1\n        else:\n            nonce = await acc.get_nonce()\n        for c in calls:\n            txs.append(await acc.sign_invoke_v3(calls=[c], nonce=nonce, resource_bounds=BIG)); nonce += 1\n        print(f\"Simulation de {len(txs)} transaction(s), sans frais ni envoi\u2026\")\n        try:\n            res = await client.simulate_transactions(transactions=txs, skip_fee_charge=True)\n        except Exception as e:\n            sys.exit(f\"SIMULATION REFUS\u00c9E par le r\u00e9seau :\\n{e}\")\n        total = 0\n        for i, r in enumerate(res):\n            tr = r.transaction_trace\n            rev = getattr(getattr(tr, \"execute_invocation\", None), \"revert_reason\", None)\n            fee = r.fee_estimation.overall_fee; total += fee\n            print(f\"  tx {i}: {'\u00c9CHEC \u2013 ' + str(rev) if rev else 'OK'}  (frais estim\u00e9s {fee/1e18:.4f} STRK)\")\n        print(f\"Frais totaux estim\u00e9s : {total/1e18:.4f} STRK. Envoie un peu plus que \u00e7a en STRK \u00e0 {hex(target)} avant --execute.\")\n        return\n\n    if input(f\"Taper OUI pour d\u00e9ployer et transf\u00e9rer vers {hex(to)} : \").strip() != \"OUI\":\n        sys.exit(\"Annul\u00e9.\")\n    if not deployed:\n        print(\"D\u00e9ploiement du compte\u2026\")\n        r = await Account.deploy_account_v3(address=target, class_hash=cls, salt=pk, key_pair=kp,\n                                            client=client, constructor_calldata=cd, auto_estimate=True)\n        await r.wait_for_acceptance(); print(\"  d\u00e9ploy\u00e9.\")\n    for k, c in enumerate(calls):\n        r = await acc.execute_v3(calls=[c], auto_estimate=True)\n        await client.wait_for_tx(r.transaction_hash)\n        print(f\"  lot {k + 1}/{len(calls)} transf\u00e9r\u00e9 : {hex(r.transaction_hash)}\")\n    print(\"Termin\u00e9. V\u00e9rifie sur https://voyager.online/contract/\" + hex(to))\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n";

const norm = a => "0x" + BigInt(a).toString(16).padStart(64, "0");

async function vget(path, ttl = 600) {
  const url = "https://voyager.online/api" + path;
  const cache = caches.default, key = new Request(url);
  const hit = await cache.match(key);
  if (hit) return hit.json();
  const r = await fetch(url, { headers: H });
  if (!r.ok) throw new Error("voyager " + r.status);
  const body = await r.text();
  await cache.put(key, new Response(body, { headers: { "content-type": "application/json", "cache-control": `max-age=${ttl}` } }));
  return JSON.parse(body);
}

async function holdings(addr) {
  const me = BigInt(addr);
  let path = `/nft-transfers?contract_address=${addr}&type=erc1155&limit=100`, pages = 0;
  const bal = new Map();
  while (path && pages++ < 60) {
    const j = await vget(path, 300);
    for (const t of j.items || []) {
      if (BigInt(t.nftContractAddress) !== BigInt(CONTRACT)) continue;
      const q = Number(t.quantity || 1), id = t.tokenId;
      if (BigInt(t.toAddress) === me) bal.set(id, (bal.get(id) || 0) + q);
      if (BigInt(t.fromAddress) === me) bal.set(id, (bal.get(id) || 0) - q);
    }
    if (!(j.items || []).length) break;
    path = j.pagination && j.pagination.next ? j.pagination.next : null;
  }
  return [...bal].filter(([, q]) => q > 0);
}

async function meta(id) {
  const m = await vget(`/nft/${CONTRACT}/${id}`, 86400 * 7);
  const a = {}; (m.attributes || []).forEach(x => a[(x.trait_type || "").toLowerCase()] = x.value);
  const pack = !a.artist;
  return {
    id, a: pack ? (m.name || "Pack") : a.artist, r: pack ? "K" : (RAR[(a.rarity || "").toLowerCase()] || "C"),
    n: Number(a["serial number"] || 0), s: Number(a.season || (/S2/.test(m.name || "") ? 2 : 1)),
    img: m.imageUrl || m.imageSmallUrl || null,
  };
}

async function cards(addr) {
  const h = await holdings(addr);
  const out = [];
  for (let i = 0; i < h.length; i += 12) {
    const part = await Promise.all(h.slice(i, i + 12).map(async ([id, q]) => {
      try { return { ...(await meta(id)), q }; } catch { return { id, a: "Carte #" + id.slice(0, 8), r: "C", n: 0, s: 1, q, img: null }; }
    }));
    out.push(...part);
  }
  let deployed = false;
  try { const c = await vget(`/contract/${addr}`, 300); deployed = !c.error; } catch {}
  return { address: addr, deployed, items: out };
}

const json = (o, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });

export default {
  async fetch(req, env, ctx) {
    const u = new URL(req.url);
    try {
      if (u.pathname === "/api/cards") {
        const raw = u.searchParams.get("address") || "";
        if (!/^0x[0-9a-fA-F]{1,64}$/.test(raw)) return json({ error: "adresse invalide" }, 400);
        const r = await cards(norm(raw));
        if (u.searchParams.get("format") === "ids") {
          return new Response(JSON.stringify(r.items.map(d => ({ id: d.id, q: d.q, nom: d.a }))), {
            headers: { "content-type": "application/json", "content-disposition": "attachment; filename=cartes.json" } });
        }
        return json({ ...r, items: r.items.map(({ img, ...d }) => d) });
      }
      if (u.pathname.startsWith("/img/")) {
        const id = u.pathname.slice(5);
        if (!/^\d{1,80}$/.test(id)) return new Response("bad id", { status: 400 });
        const m = await meta(id);
        if (!m.img) return new Response("no image", { status: 404 });
        const r = await fetch(m.img, { headers: { "user-agent": UA }, cf: { cacheTtl: 86400 * 30, cacheEverything: true } });
        return new Response(r.body, { status: r.status, headers: { "content-type": r.headers.get("content-type") || "image/jpeg", "cache-control": "public, max-age=2592000" } });
      }
      if (u.pathname === "/rules_rescue.py") return new Response(SCRIPT, { headers: { "content-type": "text/x-python; charset=utf-8", "content-disposition": "attachment; filename=rules_rescue.py" } });
      if (u.pathname === "/robots.txt") return new Response("User-agent: *\nAllow: /\n", { headers: { "content-type": "text/plain" } });
      if (u.pathname === "/" || u.pathname === "/index.html") return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "public, max-age=300" } });
      return new Response("Not found", { status: 404 });
    } catch (e) {
      return json({ error: String(e.message || e) }, 502);
    }
  },
};
